\title{An Extension of Matsuno's Formula for Supersingular Sharp/Flat
$\lambda$-Invariants with Non-Vanishing $\mu$}
\author{Aristotle}
\date{July 13, 2026}

\begin{document}

\begin{abstract}
Let $E$ be an elliptic curve over $\QQ$ with good supersingular reduction at the
prime $2$, and let $D$ be a squarefree integer with $D \equiv 1 \pmod 4$.
Classical results of Matsuno, Pollack--Kobayashi and Sprung express the
difference between the sharp/flat cyclotomic Iwasawa $\lambda$-invariants of the
quadratic twist $E^D$ and of $E$ as a sum of purely local contributions over the
primes $\ell \mid D$, each weighted by the $2$-adic depth
$n_\ell = \vtwo\!\big((\ell^2-1)/8\big)$ --- under the standing hypothesis that
the $2$-adic $\mu$-invariant vanishes. We formulate and establish the structural
arithmetic of the natural extension of this formula to a non-vanishing
$\mu$-invariant. When $\mu$ is a positive integer, the sharp/flat
$\lambda$-difference of $E^D$ acquires an additional term
$\mu \cdot \sum_{\ell \mid D} 2^{n_\ell}$, distributed over the same primes with
the same depth weights. We prove that this $\mu$-corrected invariant is
conservative (it reduces to the classical formula at $\mu = 0$), linear in $\mu$,
completely additive over coprime moduli, monotone in both the level and $\mu$,
and strictly larger than the classical prediction exactly when $\mu \neq 0$ and
$D$ has a prime divisor. We further show that the local $\mu$-weights inherit the
depth law $8 \cdot 2^{n_\ell} = 2^{\vtwo(\ell-1)+\vtwo(\ell+1)}$. In a
complementary part we record the exact arithmetic of the $p = 2$ sharp/flat
characteristic-degree sequences, proving $3\,(\text{flat}) + 1 = 4^n$, the ratio
$\text{sharp} = 2\,\text{flat}$, and that the flat degree equals the
even-indexed Jacobsthal number $J_{2n}$, governed by $J_{n+2} = J_{n+1} + 2 J_n$
with $3 J_n = 2^n - (-1)^n$.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Background}
Iwasawa theory studies the growth of arithmetic invariants of an elliptic curve
$E/\QQ$ along the cyclotomic $\ZZ_p$-extension $\QQ_\infty/\QQ$. In the good
\emph{ordinary} case, Mazur attached to $E$ a characteristic power series in the
Iwasawa algebra $\ZZ_p[[T]]$, whose $\lambda$- and $\mu$-invariants --- the
degree of its distinguished (Weierstrass) polynomial and the $p$-adic content of
its coefficients --- control the asymptotic size of the Selmer groups
$\mathrm{Sel}_n$ via $\#\,\mathrm{Sel}_n = p^{\,\mu p^n + \lambda n + \nu}$ for
$n \gg 0$.

In the \emph{supersingular} case the naive $p$-adic $L$-function fails to lie in
$\ZZ_p[[T]]$, and the theory bifurcates. Pollack (for $a_p = 0$) and Sprung (in
general) decomposed the situation into a plus/minus, or sharp/flat, pair of
well-behaved Iwasawa modules, each carrying its own $\lambda^\sharp,
\lambda^\flat$ and $\mu^\sharp, \mu^\flat$; Kobayashi's plus/minus Selmer groups
realize this on the algebraic side.

Comparison under \emph{quadratic twisting} by a squarefree $D$ is a recurring
theme. Matsuno, Pollack--Weston and Hatley--Ray established formulas expressing
the change in $\lambda$-invariants under a twist as a sum of local terms, one per
prime $\ell \mid D$, computable from the reduction type at $\ell$ and the
$2$-adic combinatorics of $\ell$. At $p = 2$ these local weights are governed by
the depth $n_\ell = \vtwo\!\big((\ell^2 - 1)/8\big)$. The classical statements
carry a standing hypothesis: the relevant $\mu$-invariant vanishes. This is
expected generically, but non-vanishing $\mu$ does occur, and there the classical
twist formula makes no prediction.

\subsection{Contribution}
This paper isolates and proves the arithmetic core of the extension of the
Matsuno-type twist formula to a non-vanishing $\mu$-invariant. Our thesis is that
a positive $\mu$ contributes an additional, cleanly structured term:
\[
\lambda(E^D) - \lambda(E) = \sum_{\ell \mid D} \delta(\ell)
\;+\; \mu \cdot \sum_{\ell \mid D} 2^{\,n_\ell}.
\]
We model the (not-yet-formalizable) global $\lambda$-difference by an explicit
$\NN$-valued function built from the same local data, and prove conservativity at
$\mu = 0$, linearity in $\mu$, complete additivity over coprime moduli,
monotonicity, and a sharp positivity criterion. We complement this with an exact
analysis of the $p = 2$ sharp/flat degree sequences, connecting the
powers-of-two weights $2^{n_\ell}$ to the Jacobsthal growth of the invariants.

\section{Definitions and setup}

Throughout, $\vtwo \colon \ZZ_{>0} \to \ZZ_{\geq 0}$ denotes the $2$-adic
valuation, and for a positive integer $D$ we write $\PP(D)$ for its set of
distinct prime divisors. We fix an elliptic curve $E/\QQ$ of conductor $N_E$ with
good supersingular reduction at $2$, a squarefree $D \equiv 1 \pmod 4$, and a
non-negative integer $\mu$ standing for the (common) $2$-adic $\mu$-invariant.
The reduction order $\mathrm{ord}(\ell)$ is a fixed arithmetic function of
$\ell$; only its parity enters the formula.

\begin{definition}[2-adic depth]
For a prime $\ell$, the \emph{depth} is
$n_\ell = \vtwo\!\big((\ell^2 - 1)/8\big)$.
\end{definition}

\begin{definition}[Classical local term]
The classical local contribution of a prime $\ell$ is
\[
\delta(\ell) =
\begin{cases}
2^{\,n_\ell} & \text{if } \ell \mid N_E, \\
2^{\,n_\ell + 1} & \text{if } \ell \nmid N_E \text{ and } 2 \mid \mathrm{ord}(\ell), \\
0 & \text{otherwise.}
\end{cases}
\]
\end{definition}

\begin{definition}[Classical Matsuno difference]
$\displaystyle \Lambda_0(D) = \sum_{\ell \in \PP(D)} \delta(\ell).$
\end{definition}

\begin{definition}[Local $\mu$-weight]
Each prime $\ell$ carries the weight $w(\ell) = 2^{\,n_\ell}$.
\end{definition}

\begin{definition}[$\mu$-term]
$\displaystyle M(D,\mu) = \mu \cdot \sum_{\ell \in \PP(D)} w(\ell)
= \mu \cdot \sum_{\ell \mid D} 2^{\,n_\ell}.$
\end{definition}

\begin{definition}[$\mu$-corrected Matsuno difference]
$\displaystyle \Lambda(D,\mu) = \Lambda_0(D) + M(D,\mu).$
\end{definition}

\section{The $\mu$-corrected Matsuno invariant}

\begin{theorem}[Additivity of the classical term]\label{thm:add0}
If $a, b \geq 1$ are coprime, then $\Lambda_0(ab) = \Lambda_0(a) + \Lambda_0(b)$.
\end{theorem}
\begin{proof}[Proof sketch]
For coprime $a, b$ the prime-divisor sets are disjoint and $\PP(ab) = \PP(a)
\sqcup \PP(b)$; the defining sum splits over the disjoint union.
\end{proof}

\begin{theorem}[Single prime]\label{thm:prime0}
For a prime $p$, $\Lambda_0(p) = \delta(p)$.
\end{theorem}
\begin{proof}[Proof sketch]
$\PP(p) = \{p\}$ is a singleton, so the defining sum has one term.
\end{proof}

\begin{theorem}[Conservativity]\label{thm:cons}
For every $D$, $\Lambda(D, 0) = \Lambda_0(D)$.
\end{theorem}
\begin{proof}[Proof sketch]
$M(D,0) = 0$, so $\Lambda(D,0) = \Lambda_0(D) + 0$.
\end{proof}

\begin{theorem}[The $\mu$-contribution]\label{thm:contrib}
$\Lambda(D,\mu) - \Lambda_0(D) = M(D,\mu)$.
\end{theorem}
\begin{proof}[Proof sketch]
Immediate from $\Lambda = \Lambda_0 + M$ with non-negative summands.
\end{proof}

\begin{theorem}[Linearity in $\mu$]\label{thm:lin}
$M(D, a + b) = M(D, a) + M(D, b)$ and $M(D, \mu) = \mu \cdot M(D, 1)$.
\end{theorem}
\begin{proof}[Proof sketch]
Both follow from $M(D,\mu) = \mu\,S$ with $S = \sum_{\ell \mid D} w(\ell)$
independent of $\mu$: distributivity and $\mu S = \mu(1 \cdot S)$.
\end{proof}

\begin{theorem}[Additivity of the $\mu$-term]\label{thm:addM}
If $a, b \geq 1$ are coprime, then $M(ab, \mu) = M(a, \mu) + M(b, \mu)$.
\end{theorem}
\begin{proof}[Proof sketch]
As in Theorem~\ref{thm:add0}, $\sum_{\ell \mid ab} w(\ell) = \sum_{\ell \mid a}
w(\ell) + \sum_{\ell \mid b} w(\ell)$; multiply by $\mu$.
\end{proof}

\begin{theorem}[Complete additivity]\label{thm:addfull}
If $a, b \geq 1$ are coprime, then $\Lambda(ab, \mu) = \Lambda(a, \mu) +
\Lambda(b, \mu)$.
\end{theorem}
\begin{proof}[Proof sketch]
Combine Theorems~\ref{thm:add0} and~\ref{thm:addM} term by term and regroup.
This is the arithmetic reflection of the multiplicativity of quadratic twisting.
\end{proof}

\begin{theorem}[Single prime, corrected]\label{thm:primeM}
For a prime $p$, $\Lambda(p, \mu) = \delta(p) + \mu \cdot 2^{\,n_p}$.
\end{theorem}
\begin{proof}[Proof sketch]
Apply Theorem~\ref{thm:prime0} and $M(p,\mu) = \mu \cdot 2^{n_p}$.
\end{proof}

\begin{theorem}[Monotonicity in the level]\label{thm:monlev}
If $d \mid D$ and $D \neq 0$, then $\Lambda(d, \mu) \leq \Lambda(D, \mu)$.
\end{theorem}
\begin{proof}[Proof sketch]
$\PP(d) \subseteq \PP(D)$ and all summands are non-negative; add the classical
and $\mu$-part inequalities.
\end{proof}

\begin{theorem}[Monotonicity in $\mu$]\label{thm:monmu}
If $\mu \leq \mu'$, then $\Lambda(D, \mu) \leq \Lambda(D, \mu')$.
\end{theorem}
\begin{proof}[Proof sketch]
Only the $\mu$-term depends on $\mu$, and it is $\mu$ times a fixed non-negative
sum.
\end{proof}

\begin{lemma}[Positivity of weights and total weight]\label{lem:pos}
$w(\ell) = 2^{n_\ell} > 0$, and $\sum_{\ell \mid D} w(\ell) > 0$ iff
$\PP(D) \neq \varnothing$.
\end{lemma}
\begin{proof}[Proof sketch]
A sum of strictly positive terms is positive iff the index set is nonempty; an
empty sum is $0$.
\end{proof}

\begin{theorem}[Positivity criterion]\label{thm:poscrit}
$M(D, \mu) > 0$ if and only if $\mu > 0$ and $\PP(D) \neq \varnothing$.
\end{theorem}
\begin{proof}[Proof sketch]
$M(D,\mu) = \mu \cdot S$ is nonzero iff both factors are; apply
Lemma~\ref{lem:pos}.
\end{proof}

\begin{theorem}[A non-vanishing $\mu$ is always visible]\label{thm:visible}
If $\mu > 0$ and $\PP(D) \neq \varnothing$, then $\Lambda_0(D) < \Lambda(D,\mu)$.
\end{theorem}
\begin{proof}[Proof sketch]
By Theorem~\ref{thm:poscrit} the $\mu$-term is strictly positive, and
$\Lambda(D,\mu) = \Lambda_0(D) + M(D,\mu)$. Both hypotheses are necessary.
\end{proof}

\section{The depth law for the $\mu$-weights}

\begin{lemma}[Divisibility by eight]\label{lem:eight}
For every odd $\ell$, $8 \mid \ell^2 - 1$.
\end{lemma}
\begin{proof}[Proof sketch]
$\ell^2 - 1 = (\ell-1)(\ell+1)$ is a product of two consecutive even numbers,
one divisible by $4$.
\end{proof}

\begin{lemma}[Valuation form of the depth]\label{lem:valdepth}
For odd $\ell \geq 3$, $\vtwo(\ell^2 - 1) = n_\ell + 3$.
\end{lemma}
\begin{proof}[Proof sketch]
Write $\ell^2 - 1 = 8 \cdot \frac{\ell^2 - 1}{8}$; the factor $8 = 2^3$
contributes $3$ and the quotient contributes $n_\ell$ by definition, using
multiplicativity of $\vtwo$.
\end{proof}

\begin{lemma}[Factored depth]\label{lem:factdepth}
For odd $\ell \geq 3$, $n_\ell + 3 = \vtwo(\ell - 1) + \vtwo(\ell + 1)$.
\end{lemma}
\begin{proof}[Proof sketch]
Factor $\ell^2 - 1 = (\ell-1)(\ell+1)$ and apply multiplicativity of $\vtwo$ with
Lemma~\ref{lem:valdepth}.
\end{proof}

\begin{theorem}[Depth law for $\mu$-weights]\label{thm:depthlaw}
For odd $\ell \geq 3$,
$8 \cdot 2^{\,n_\ell} = 2^{\,\vtwo(\ell - 1) + \vtwo(\ell + 1)}$.
\end{theorem}
\begin{proof}[Proof sketch]
By Lemma~\ref{lem:factdepth} the right exponent is $n_\ell + 3$, so the
right-hand side is $2^{n_\ell + 3} = 8 \cdot 2^{n_\ell}$.
\end{proof}

The local $\mu$-weight is thus governed by the same quantity
$\vtwo(\ell-1) + \vtwo(\ell+1) - 3$ that controls the classical depth, so both
pieces of the corrected formula speak a common arithmetic language.

\section{The $p = 2$ sharp/flat degree sequences}

\begin{definition}[Flat and sharp degrees]
$\displaystyle F(n) = \sum_{i < n} 4^i, \qquad S(n) = \sum_{i < n} 2 \cdot 4^i.$
\end{definition}

\begin{theorem}[Closed form for the flat degree]\label{thm:flatclosed}
$3\,F(n) + 1 = 4^n$; equivalently $F(n) = (4^n - 1)/3$.
\end{theorem}
\begin{proof}[Proof sketch]
Induction: base $3\cdot 0 + 1 = 4^0$; step uses $F(n+1) = F(n) + 4^n$ and
$4 \cdot 4^n = 4^{n+1}$.
\end{proof}

\begin{theorem}[Sharp/flat ratio, total, difference]\label{thm:ratio}
$S(n) = 2\,F(n)$, \; $S(n) + F(n) + 1 = 4^n$, \; and $S(n) - F(n) = F(n)$.
\end{theorem}
\begin{proof}[Proof sketch]
Pull out the factor $2$ for the ratio; substitute into Theorem~\ref{thm:flatclosed}
for the total and difference.
\end{proof}

\begin{theorem}[Recurrence and strict growth]\label{thm:rec}
$F(n+1) = 4\,F(n) + 1$, and $F$ is strictly increasing.
\end{theorem}
\begin{proof}[Proof sketch]
Compare $3F(n)+1 = 4^n$ with $3F(n+1)+1 = 4^{n+1}$; then $F(n+1) > F(n)$.
\end{proof}

\begin{definition}[Jacobsthal sequence]
$J_0 = 0$, $J_1 = 1$, $J_{n+2} = J_{n+1} + 2\,J_n$.
\end{definition}

\begin{theorem}[Closed form]\label{thm:jacclosed}
$3\,J_n = 2^n - (-1)^n$.
\end{theorem}
\begin{proof}[Proof sketch]
Strong induction; the step uses the recurrence with
$2^{n+2} = 2^{n+1} + 2\cdot 2^n$ and $(-1)^{n+2} = (-1)^{n+1} + 2(-1)^n$.
\end{proof}

\begin{theorem}[Consecutive sum]\label{thm:jacsum}
$J_n + J_{n+1} = 2^n$.
\end{theorem}
\begin{proof}[Proof sketch]
Add the closed forms for $n$ and $n+1$: the alternating terms cancel and
$2^n + 2^{n+1} = 3 \cdot 2^n$.
\end{proof}

\begin{theorem}[Flat degree is a Jacobsthal number]\label{thm:flatjac}
$J_{2n} = F(n)$.
\end{theorem}
\begin{proof}[Proof sketch]
$3 J_{2n} = 4^n - 1 = 3 F(n)$ by Theorems~\ref{thm:jacclosed}
and~\ref{thm:flatclosed}.
\end{proof}

The flat-degree sequence is therefore
$0, 1, 5, 21, 85, 341, 1365, \ldots = J_0, J_2, J_4, \ldots$, closing the loop:
the $\mu$-weights are powers of two, consecutive Jacobsthal numbers sum to a
power of two (Theorem~\ref{thm:jacsum}), and the flat degree is an even-indexed
Jacobsthal number.

\section{Discussion and future work}

Because a fully general theory of sharp/flat cyclotomic $\lambda$-invariants is
not yet available in the ambient formal framework, we model the global
$\lambda$-difference by an explicit $\NN$-valued function assembled from the
genuine local ingredients. This isolates the combinatorial and arithmetic
content of the extension --- additivity, linearity, monotonicity, positivity,
the depth law --- from the analytic construction of the invariants, and every
theorem above constrains any faithful definition of the true invariants.

\medskip
\noindent\textbf{Future directions.}
\begin{enumerate}[leftmargin=2em]
\item \emph{Genuine Iwasawa invariants.} Replace the modeled difference and
$\mu$-term by actual $\lambda$- and $\mu$-invariants from a characteristic power
series in $\ZZ_2[[T]]$ via Weierstrass preparation, and prove
$\lambda(fg) = \lambda(f) + \lambda(g)$, $\mu(fg) = \mu(f) + \mu(g)$.
\item \emph{Sharp/flat Coleman maps.} Formalize Pollack's $\omega_n^\pm$ and
Sprung's sharp/flat decomposition and identify their degrees with the flat/sharp
sequences here.
\item \emph{The full twist formula.} Derive the local terms $2^{n_\ell}$,
$2^{n_\ell + 1}$ from local Tamagawa/reduction data at $\ell$.
\item \emph{General supersingular primes $p$.} Generalize the Jacobsthal
identities to $q_n = (p^n - (-1)^n)/(p+1)$ and the degree sums to base $p^2$.
\item \emph{Hatley--Ray comparison.} Connect the additive $\mu$-correction to
comparison results for congruent modular forms.
\end{enumerate}

