from typing import Callable, List

def padic_val(p: int, n: int) -> int:
    if n == 0: return 0
    v = 0
    while n % p == 0: n //= p; v += 1
    return v

def prime_factors(n: int) -> List[int]:
    fs, d, m = [], 2, n
    while d*d <= m:
        if m % d == 0:
            fs.append(d)
            while m % d == 0: m //= d
        d += 1
    if m > 1: fs.append(m)
    return fs

def n_ell(ell: int) -> int: return padic_val(2, (ell**2 - 1)//8)

def lambda_diff(D, N, ordf): 
    tot = 0
    for l in prime_factors(D):
        nl = n_ell(l)
        tot += 2**nl if N % l == 0 else (2**(nl+1) if ordf(l)%2==0 else 0)
    return tot

def mu_term(D, mu): return mu * sum(2**n_ell(l) for l in prime_factors(D))

if __name__ == '__main__':
    N = 15; ordf: Callable[[int], int] = lambda l: l - 1
    for D in [5, 13, 65, 5*13*17]:
        base = lambda_diff(D, N, ordf)
        print(f'D={D}: classical={base}')
        for mu in range(4):
            print(f'  mu={mu}: corrected={base + mu_term(D, mu)}'
                  f' (extra={mu_term(D, mu)})')

def flat_deg(n): return sum(4**i for i in range(n))
def sharp_deg(n): return sum(2*4**i for i in range(n))

def jacobsthal(n):
    a, b = 0, 1
    if n == 0: return 0
    for _ in range(n-1): a, b = b, b + 2*a
    return b

if __name__ == '__main__':
    print(f"{'n':>3}{'flat':>8}{'sharp':>9}{'4^n':>9}{'J_2n':>9}")
    for n in range(9):
        f, s, j = flat_deg(n), sharp_deg(n), jacobsthal(2*n)
        assert s == 2*f and s + f + 1 == 4**n and 3*f + 1 == 4**n
        assert j == f
        print(f'{n:>3}{f:>8}{s:>9}{4**n:>9}{j:>9}')
    for n in range(12):
        assert 3*jacobsthal(n) == 2**n - (-1)**n
        assert jacobsthal(n) + jacobsthal(n+1) == 2**n
    print('All Jacobsthal identities verified.')

