from typing import Callable, List

def padic_val(p: int, n: int) -> int:
    if n == 0:
        return 0
    v = 0
    while n % p == 0:
        n //= p
        v += 1
    return v

def prime_factors(n: int) -> List[int]:
    factors: List[int] = []
    d, m = 2, n
    while d * d <= m:
        if m % d == 0:
            factors.append(d)
            while m % d == 0:
                m //= d
        d += 1
    if m > 1:
        factors.append(m)
    return factors

def n_ell(ell: int) -> int:
    return padic_val(2, (ell ** 2 - 1) // 8)

def lambda_diff_mu(D: int, conductor: int, mu: int,
                   ord_map: Callable[[int], int]) -> int:
    total = 0
    for ell in prime_factors(D):
        nl = n_ell(ell)
        if conductor % ell == 0:
            delta = 2 ** nl
        elif ord_map(ell) % 2 == 0:
            delta = 2 ** (nl + 1)
        else:
            delta = 0
        total += delta + mu * 2 ** nl
    return total

