function SharpFlatDegrees(n):
    a, b <- 0, 1                # J_0, J_1
    for k from 1 to 2n - 1:
        a, b <- b, b + 2 * a    # advance Jacobsthal
    flat <- a if n == 0 else (a if (2n) even else b)  # J_{2n}
    sharp <- 2 * flat
    assert 3 * flat + 1 == 4^n
    return (flat, sharp)

