def jacobsthal(n: int) -> int:
    a, b = 0, 1
    if n == 0:
        return a
    for _ in range(n - 1):
        a, b = b, b + 2 * a
    return b

def sharp_flat_degrees(n: int) -> Tuple[int, int]:
    flat = jacobsthal(2 * n)          # F(n) = J_{2n}
    sharp = 2 * flat                  # sharp = 2 * flat
    assert 3 * flat + 1 == 4 ** n     # closed-form cross-check
    assert sharp + flat + 1 == 4 ** n
    return flat, sharp

