def padic_val(p: int, n: int) -> int:
    if n == 0:
        return 0
    v = 0
    while n % p == 0:
        n //= p
        v += 1
    return v

def check_depth_law(ell: int) -> bool:
    assert ell % 2 == 1 and ell >= 3
    n_l = padic_val(2, (ell ** 2 - 1) // 8)
    e = padic_val(2, ell - 1) + padic_val(2, ell + 1)
    return (n_l + 3 == e) and (8 * 2 ** n_l == 2 ** e)
